let table = {{workflowparams:allData}};

if(table.srr_no_type !== -9999 && (
  !table.srr_no|| table.srr_no === null || table.srr_no === ''
)) {
  table.srr_no = 'draft'
}

return { table };

let table = {{workflowparams:allData}};

if (
  table.srr_no_type !== -9999 &&
  (!table.srr_no ||
    table.srr_no === null ||
    table.srr_no === "" ||
    table.previous_status == "Draft")
) {
  table.srr_no = 'issued'
}

return { table };

const entry = {{node:code_node_Rr54LMQQ.data.table}};

const srLineIDs = entry.table_srr.map(item => item.sr_line_id);

return { srLineIDs }

const entry = {{node:code_node_Rr54LMQQ.data.table}};
const srLineItemList = {{node:search_node_yBcXo9Ht.data.data}};

// One SR line can span several SRR rows (one per source batch), so the
// receivable check has to aggregate per SR line instead of per row.
const requestedBySRLine = {};

for (const item of entry.table_srr) {
  if (!item.sr_line_id) continue;
  requestedBySRLine[item.sr_line_id] =
    (requestedBySRLine[item.sr_line_id] || 0) + parseFloat(item.received_qty || 0);
}

let invalidReceivedQty = [];

for (const srLine of srLineItemList) {
  const maxReceivableQty = parseFloat(srLine.expected_return_qty || 0) - parseFloat(srLine.received_qty || 0);
  if ((requestedBySRLine[srLine.id] || 0) > maxReceivableQty) {
    for (const [index, item] of entry.table_srr.entries()) {
      if (item.sr_line_id === srLine.id) {
        invalidReceivedQty.push(`#${index + 1}`);
      }
    }
  }
}

if(invalidReceivedQty.length > 0) {
  return {
    status: 'Failed',
    message: `Line${invalidReceivedQty.length > 1 ? "s" : ""} ${invalidReceivedQty.join(
        ", ",
      )} ha${
        invalidReceivedQty.length > 1 ? "ve" : "s"
      } an expected receive quantity exceeding the maximum receivable quantity.`
  }
}

// new_batch = 0 means stock returns into the batch it was delivered from. A
// batch-managed row that reaches here without a resolved batch_id would
// otherwise be posted under whatever placeholder batch_no still holds.
if (parseFloat(entry.new_batch) === 0) {
  let missingBatch = [];

  for (const [index, item] of entry.table_srr.entries()) {
    if (!item.batch_id && item.batch_no && item.batch_no !== '-') {
      missingBatch.push(`#${index + 1}`);
    }
  }

  if (missingBatch.length > 0) {
    return {
      status: 'Failed',
      message: `Line${missingBatch.length > 1 ? "s" : ""} ${missingBatch.join(
          ", ",
        )} ha${
          missingBatch.length > 1 ? "ve" : "s"
        } no source batch. This plant returns stock into the batch it was delivered from, so please re-add the item(s) to resolve the delivered batch.`
    }
  }
}

return {
  status: 'Success',
  message: ''
}

let entry = {{node:code_node_Rr54LMQQ.data.table}}

// Check total return qty
const totalQuantity = entry.table_srr.reduce((sum, item) => {
    const { received_qty } = item;
    return sum + (received_qty || 0);
  }, 0);

if(totalQuantity <= 0){
  return {
    status: 'Failed',
    code: '403',
    message: 'Total received quantity is 0.',
    entry
  }
}

// Check line received qty
let zeroQtyArray = [];
for(const [index, sr] of entry.table_srr.entries()) {
  if (parseFloat(sr.received_qty) <= 0) {
    zeroQtyArray.push(`#${index + 1}`);
  }
}

if(zeroQtyArray.length > 0) {
  if(entry.filter_srr == 'Yes') {
    if(entry.new_batch == 1){
      entry.table_srr = entry.table_srr.filter(
        (item) => item.received_qty > 0,
      );
    }

    if(entry.table_srr.length === 0) {
      return {
        status: 'Failed',
        code: '405',
        message: 'All Received Quantity must not be 0. Please add at least one item with received quantity > 0.',
        entry
      }
    }

    let salesOrderNumber = [];
    let soId = [];
    let goodsDeliveryNumber = [];
    let gdId = [];
    let salesReturnNumber = [];
    let srId = [];

    for (const srr of entry.table_srr) {
      gdId.push(srr.gd_id);
      goodsDeliveryNumber.push(srr.gd_number);

      soId.push(srr.so_id);
      salesOrderNumber.push(srr.so_number);

      srId.push(srr.sr_id);
      salesReturnNumber.push(srr.sr_number);
    }

    soId = [...new Set(soId)];
    gdId = [...new Set(gdId)];
    srId = [...new Set(srId)];
    salesOrderNumber = [...new Set(salesOrderNumber)];
    goodsDeliveryNumber = [...new Set(goodsDeliveryNumber)];
    salesReturnNumber = [...new Set(salesReturnNumber)];

    entry.so_id = soId;
    entry.gd_id = gdId;
    entry.sr_id = srId;
    entry.so_no_display = salesOrderNumber.join(", ");
    entry.gd_no_display = goodsDeliveryNumber.join(", ");
    entry.sr_no_display = salesReturnNumber.join(", ");
  } else {
    return {
      status: 'Failed',
      code: '404',
      message: `Line${zeroQtyArray.length > 1 ? "s" : ""} ${zeroQtyArray.join(", ")} ha${
        zeroQtyArray.length > 1 ? "ve" : "s"
      } a zero received quantity, which may prevent processing.\nIf you proceed, it will delete the row with 0 received quantity. \nWould you like to proceed?`,
      entry
    }
  }
}

return {
  status: 'Success',
  code: '',
  message: '',
  entry
}

const allData = {{workflowparams:allData}};
const userID = {{system:uid}};
const newDate = new Date();
const unique = `${userID || ""}_${newDate}`;

return {
  unique
};

const allData = {{node:code_node_gfkN0Qq7.data.entry}};
const subformData = allData.table_srr || [];
const currentIndexRaw = {{node:get_cache_node_ZCcCicY6.data}};
const index = currentIndexRaw ? parseInt(currentIndexRaw, 10) : 0;
const item = subformData[index] || {};

// Only generate for auto-batch rows that are NOT hierarchy children
// (children inherit the parent batch number after the loop)
const needsGen = (item.batch_no === "Auto-generated batch number") ? 1 : 0;

return {
  item_id: item.material_id || "",
  needsGen: needsGen,
  document_date: allData.received_date || '',
  manufacturing_date: item.manufacturing_date || '',
  expired_date: item.expired_date || '',
  index: index,
  nextIndex: index + 1
};

const data = {{node:workflow_node_lp2Gbzjg.data}} || {};
const batchNumber = data.batch_number || "";
const isError = batchNumber ? 0 : 1;
const message = data.message || data.msg || "Failed to generate batch number. Please ensure a Batch Number Configuration is set up for this item or organization.";

return { batchNumber, isError, message };

const cachedRaw = {{node:get_cache_node_CUypNBeX.data}};
const arr = Array.isArray(cachedRaw) ? cachedRaw : (cachedRaw ? JSON.parse(cachedRaw) : []);
const index = {{node:code_node_zBFHqHSZ.data.index}};
const batchNumber = {{node:code_node_n04I7LW1.data.batchNumber}};

arr.push({ index: index, batch_number: batchNumber });

return { generatedBatches: arr };

const allData = {{node:code_node_gfkN0Qq7.data.entry}};
const tableSRR = allData.table_srr || [];
const generatedRaw = {{node:get_cache_node_BGYDiORv.data}};
const generated = Array.isArray(generatedRaw) ? generatedRaw : (generatedRaw ? JSON.parse(generatedRaw) : []);

// Overlay generated batch numbers onto their rows by index
const genMap = {};
for (const g of generated) {
  genMap[g.index] = g.batch_number;
}
for (let i = 0; i < tableSRR.length; i++) {
  if (genMap[i] !== undefined && genMap[i] !== null) {
    tableSRR[i].batch_no = genMap[i];
  }
}

return { entry: { ...allData, table_srr: tableSRR } };

const newBatch = {{workflowparams:allData.new_batch}};

const entry = newBatch === 1 ? {{node:code_node_Od28Av8v.data.entry}} : {{node:code_node_gfkN0Qq7.data.entry}};

return { entry };

let entry = {{workflowparams:allData.srr_status}} === 'Draft' ? {{node:code_node_pQlxXrFl.data.table}} : {{node:code_node_hGkumbo8.data.entry}};
let updatedLineItem = [];

for(const [index, srrLineItem] of entry.table_srr.entries()) {
  // Create a new object with formatted values
  const formattedItem = {
    ...srrLineItem,
    // Number formatting
    so_quantity: parseFloat(srrLineItem.so_quantity || 0).toFixed(3),
    expected_return_qty: parseFloat(srrLineItem.expected_return_qty || 0).toFixed(3),
    to_receive_qty: parseFloat(srrLineItem.to_receive_qty || 0).toFixed(3),
    gd_quantity: parseFloat(srrLineItem.gd_quantity || 0).toFixed(3),
    unit_price: parseFloat(srrLineItem.unit_price || 0).toFixed(4),
    total_price: parseFloat(srrLineItem.total_price || 0).toFixed(4),

    customer_id: entry.customer_id || null,
    plant_id: entry.plant_id || null,
  };

  updatedLineItem.push(formattedItem);
}

entry.table_srr = updatedLineItem;

return { entry }

const srrLineItem = {{node:loop_mWCnGwvG}};
const entry = {{node:code_node_AQ8blgDy.data.srrData}};

return { inventoryData: {
  ...srrLineItem,
  plant_id: entry.plant_id,
  organization_id: entry.organization_id,
  trx_no: entry.srr_no,
  received_date: entry.received_date,
  batch_id: srrLineItem.batch_id ?? null,
  batch_no: !srrLineItem.batch_id ? srrLineItem.batch_no : null,
} }

const srLineItemList = {{node:search_node_yBcXo9Ht.data.data}};
const srrData = {{node:code_node_AQ8blgDy.data.srrData}};
let latestSRLineItemList = [];

for(const srLineItem of srLineItemList) {
  const receivedQty = srrData.table_srr
  .filter(item => item.sr_line_id === srLineItem.id)
  .reduce((total, item) => total + (parseFloat(item.received_qty) || 0), 0);

  const latestReceivedQty = parseFloat(receivedQty) + parseFloat(srLineItem.received_qty || 0);

  latestSRLineItemList.push({
    id: srLineItem.id,
    received_qty: latestReceivedQty.toFixed(3),
    srr_status: parseFloat(latestReceivedQty) >= parseFloat(srLineItem.expected_return_qty || 0) ? "Fully Received" : "Partially Received",
  })
}

return { latestSRLineItemList }

const srList = {{node:search_node_9xxdyv7Z.data.data}};

const latestSRList = srList.map((item, index) => {
  const updatedSRStatus = item.table_sr.some(
    (srItem) =>
      parseFloat(srItem.received_qty || 0) < parseFloat(srItem.expected_return_qty || 0),
  )
    ? "Partially Received"
    : "Fully Received";

  return {
    id: item.id,
    srr_status: updatedSRStatus,
    sr_status: updatedSRStatus === 'Fully Received' ? 'Completed' : 'Processing'
  };
});

return { latestSRList }

const srSetup = {{node:get_node_wuqT9kxg.data.data}} ?? null;

if(!srSetup || !srSetup.id || srSetup.id === '') {
  return {
    createCN: 'No'
  }
} else {
  return {
    createCN: srSetup.auto_cn != 1 || srSetup.trigger_by != 'Sales Return Receiving' ? 'No' : 'Yes'
  }
}

const srrData = {{node:code_node_AQ8blgDy.data.srrData}};

const gdLineIDs = [ ...new Set(srrData.table_srr.map(item => item.gd_line_id))]

return { gdLineIDs }

const siList = {{node:search_node_hx3J9PHc.data.data}};
const siLineItemList = {{node:search_node_n6abggZu.data.data}};
const srrData = {{node:code_node_AQ8blgDy.data.srrData}};

// Condition 1: one gd_line_id must map to exactly one SI
const gdLineToSIMap = {};
for (const siLine of siLineItemList) {
  if (!siLine.gd_line_id) continue;
  if (gdLineToSIMap[siLine.gd_line_id]) {
    return {
      status: 'Failed',
      message: `GD is mapped to more than one SI.`
    };
  }
  gdLineToSIMap[siLine.gd_line_id] = siLine.si_id;
}

// Condition 2: one SI must map to exactly one gd_id in srrData
const multipleGDSI = siList.filter(si => si.gd_id.length > 1)
if(multipleGDSI.length > 0) {
  return {
    status: 'Failed',
    message: `SI contains more than one GDs.`
  };
}

// Condition 3 & 4: check per SR line
for (const [index, srr] of srrData.table_srr.entries()) {
  const matchedSILine = siLineItemList.find(line => line.gd_line_id === srr.gd_line_id);
  if (!matchedSILine) {
    return {
      status: 'Failed',
      message: `No matching SI line found for GD Line ID ${srr.gd_line_id}.`
    };
  }

  // Condition 3: invoice_qty must be greater than return qty
  const receivedQty = parseFloat(srr?.received_qty) ?? 0;
  if (parseFloat(matchedSILine.invoice_qty) - parseFloat(matchedSILine.credit_qty) < receivedQty) {
    return {
      status: 'Failed',
      message: `Invoice quantity (${matchedSILine.invoice_qty}) must be greater than received quantity (${receivedQty}).`
    };
  }

  // Condition 4: si_amount must be greater than 0
  if (matchedSILine.si_amount <= 0) {
    return {
      status: 'Failed',
      message: `Invoice line total must be greater than 0.`
    };
  }
}

return {
  status: 'Passed',
  message: ''
};

const formatNumberTo4 = (value) => {
  if (value === null || value === undefined || value === "") return "0.0000";
  return parseFloat(value).toFixed(4);
};

const formatNumberTo3 = (value) => {
  if (value === null || value === undefined || value === "") return "0.000";
  return parseFloat(value).toFixed(3);
};

const roundTo4 = (value) => {
  return Math.round((parseFloat(value) || 0) * 10000) / 10000;
};

const calculateFinalPrice = (total, invoiceQty, creditQty) => {
  const priceForCredit =
    (roundTo4(total) / roundTo4(invoiceQty)) * roundTo4(creditQty);

  return roundTo4(priceForCredit);
};

const sumPrice = (fieldName, cnLineItemList) => {
  return roundTo4(
    cnLineItemList.reduce((total, item) => {
      return roundTo4(total) + roundTo4(item[fieldName]);
    }, 0),
  );
};

const srrData = {{node:code_node_AQ8blgDy.data.srrData}};
const siLineItemList = {{node:search_node_n6abggZu.data.data}};
const siList = {{node:search_node_hx3J9PHc.data.data}};
const cnDocFormat = {{node:get_node_ND9kvc1X.data.data}};
const customerData = {{node:get_node_L3pzh9TR.data.data}};
const currencyCode = {{node:get_node_MGTKHG7i.data.data}};
const shippingAddress = {{node:get_node_PEmhp9gc.data.data}};
const billingAddress = {{node:get_node_PCvTL2sg.data.data}};
let cnLineItemList = [];

for (const [index, srrLineItem] of srrData.table_srr.entries()) {
  const matchedSILineItem = siLineItemList.find(
    (item) => item.gd_line_id === srrLineItem.gd_line_id,
  );

  const matchedSI = siList.find(
    (item) => item.id === matchedSILineItem.sales_invoice_id,
  );

  const cnLineItem = {
    si_id: matchedSILineItem?.sales_invoice_id || "",
    item_id: srrLineItem.material_id,
    item_name: srrLineItem.material_name,
    uom_id: srrLineItem.quantity_uom,
    credit_qty: formatNumberTo3(srrLineItem.received_qty),
    unit_price: formatNumberTo4(matchedSILineItem.unit_price),
    subtotal:
      roundTo4(srrLineItem.received_qty) *
      roundTo4(matchedSILineItem.unit_price),
    discount: roundTo4(matchedSILineItem.si_discount),
    discount_type: matchedSILineItem?.si_discount_uom_id || "",
    discount_amount: calculateFinalPrice(
      matchedSILineItem.discount_amount,
      matchedSILineItem.invoice_qty,
      srrLineItem.received_qty,
    ),
    tax_code: matchedSILineItem?.si_tax_rate_id || "",
    tax_percent: matchedSILineItem?.tax_percent || "",
    tax_amount: calculateFinalPrice(
      matchedSILineItem.tax_amount,
      matchedSILineItem.invoice_qty,
      srrLineItem.received_qty,
    ),
    total: calculateFinalPrice(
      matchedSILineItem.si_amount,
      matchedSILineItem.invoice_qty,
      srrLineItem.received_qty,
    ),
    line_status: "Closed",
    line_index: index + 1,
    si_line_id: matchedSILineItem?.id || "",
    sr_line_id: srrLineItem.sr_line_id,
    sr_id: srrLineItem.sr_id,
    plant_id: srrData.plant_id,
    customer_id: srrData.customer_id,
    tax_inclusive: matchedSILineItem?.si_tax_inclusive || 0,
    invoice_qty: formatNumberTo3(matchedSILineItem.invoice_qty),
    item_desc: srrLineItem.receiving_detail,
    si_no: matchedSI?.sales_invoice_no || "",
    more_desc: srrLineItem.more_desc,
    available_credit_qty: formatNumberTo3(
      matchedSILineItem.invoice_qty - matchedSILineItem.credit_qty,
    ),
  };

  cnLineItemList.push(cnLineItem);
}

const cnData = {
  cn_status: "Completed",
  page_status: "Add",
  acc_integration_type: srrData.acc_integration_type,
  organization_id: srrData.organization_id,
  previous_status: null,
  plant_id: srrData.plant_id,
  customer_id: srrData.customer_id,
  currency_code: currencyCode?.currency_code || "",
  cn_no: "issued",
  cn_no_type: cnDocFormat.id,
  cn_date: new Date().toISOString().split("T")[0],
  cn_type: "Return",
  source_type: "Sales Invoice",
  source_id: [...new Set(cnLineItemList.map((item) => item.si_id))],
  source_no: [...new Set(cnLineItemList.map((item) => item.si_no))].join(", "),
  sales_return_id: [...new Set(cnLineItemList.map((item) => item.sr_id))],
  total_gross_currency: currencyCode?.currency_code || "",
  total_discount_currency: currencyCode?.currency_code || "",
  total_tax_currency: currencyCode?.currency_code || "",
  total_amount_currency: currencyCode?.currency_code || "",
  total_amount_myr: "MYR",
  subtotal: sumPrice("subtotal", cnLineItemList),
  total_discount: sumPrice("discount_amount", cnLineItemList),
  tax_total: sumPrice("tax_amount", cnLineItemList),
  grand_total: sumPrice("total", cnLineItemList),
  myr_grand_total:
    sumPrice("total", cnLineItemList) *
    roundTo4(currencyCode.currency_buying_rate),
  table_cn: cnLineItemList,
  remark: srrData.remarks,
  billing_address_name: billingAddress.address_name ?? null,
  billing_address_phone: billingAddress.address_phone ?? null,
  billing_address_line_1: billingAddress.address_line_1 ?? null,
  billing_address_line_2: billingAddress.address_line_2 ?? null,
  billing_address_line_3: billingAddress.address_line_3 ?? null,
  billing_address_line_4: billingAddress.address_line_4 ?? null,
  billing_address_city: billingAddress.address_city ?? null,
  billing_postal_code: billingAddress.address_postal_code ?? null,
  billing_address_state: billingAddress.adddress_state ?? null,
  billing_address_country: billingAddress.address_country_id ?? null,
  billing_attention: billingAddress.address_attention ?? null,
  shipping_address_name: shippingAddress.address_name ?? null,
  shipping_address_phone: shippingAddress.address_phone ?? null,
  shipping_address_line_1: shippingAddress.address_line_1 ?? null,
  shipping_address_line_2: shippingAddress.address_line_2 ?? null,
  shipping_address_line_3: shippingAddress.address_line_3 ?? null,
  shipping_address_line_4: shippingAddress.address_line_4 ?? null,
  shipping_address_city: shippingAddress.address_city ?? null,
  shipping_postal_code: shippingAddress.address_postal_code ?? null,
  shipping_address_country: shippingAddress.address_country_id ?? null,
  shipping_address_state: shippingAddress.adddress_state ?? null,
  shipping_attention: shippingAddress.address_attention ?? null,
  exchange_rate_myr: "MYR",
  exchange_rate_currency: currencyCode?.currency_code || "",
  exchange_rate: currencyCode?.currency_buying_rate || "1.0000",
  cn_billing_address: billingAddress.address ?? null,
  cn_shipping_address: shippingAddress.address ?? null,
  posted_status: "Unposted",
};

return { cnData };
